package org.humanjourney.core.mapfeature;
import java.util.*;
import java.util.concurrent.*;
import net.minecraft.server.packs.resources.*;
public final class FeatureReloadListener implements PreparableReloadListener {
 private record Prepared(FeatureCatalog.Data data,String error){}
 private Prepared prepare(ResourceManager manager){try{var sources=new ArrayList<FeatureCatalog.Source>();int total=0;var resources=manager.listResources("core/map_feature",id->id.getPath().endsWith(".json"));if(resources.size()>2048)throw new IllegalArgumentException("maximum 2048 feature resources");for(var e:resources.entrySet()){try(var reader=e.getValue().openAsReader()){var text=new StringBuilder();var buffer=new char[4096];int n;while((n=reader.read(buffer))!=-1){text.append(buffer,0,n);if(text.length()>2097152)throw new IllegalArgumentException(e.getKey()+" exceeds 2 MiB characters");}total+=text.length();if(total>67108864)throw new IllegalArgumentException("feature data exceeds 64 MiB characters");sources.add(new FeatureCatalog.Source(e.getKey().toString(),e.getValue().sourcePackId(),text.toString()));}}return new Prepared(FeatureCatalog.prepare(sources),null);}catch(Exception error){return new Prepared(null,error.getMessage()==null?error.toString():error.getMessage());}}
 public CompletableFuture<Void> reload(PreparationBarrier barrier,ResourceManager manager,Executor background,Executor game){return CompletableFuture.supplyAsync(()->prepare(manager),background).thenCompose(barrier::wait).thenAcceptAsync(p->{if(p.error()!=null){FeatureCatalog.reject(p.error());com.mojang.logging.LogUtils.getLogger().error("[HJ Core] Map feature reload REJECTED: {}. Keeping last valid catalog",p.error());}else{FeatureCatalog.accept(p.data());com.mojang.logging.LogUtils.getLogger().info("[HJ Core] Map features loaded: {} revision {}",p.data().features().size(),FeatureCatalog.state().revision());}},game);}
}
